'use strict';

/**
* Compute the value of `sqrt(1+x)-1` for a single-precision floating-point number.
*
* @module @stdlib/math/base/special/sqrt1pm1f
*
* @example
* var sqrt1pm1f = require( '@stdlib/math/base/special/sqrt1pm1f' );
*
* var v = sqrt1pm1f( 3.0 );
* // returns 1.0
*
* v = sqrt1pm1f( 0.5 );
* // returns ~0.225
*
* v = sqrt1pm1f( 0.02 );
* // returns ~0.01
*
* v = sqrt1pm1f( -0.5 );
* // returns ~-0.293
*/

// MODULES //

var sqrt1pm1f = require( './main.js' );


// EXPORTS //

module.exports = sqrt1pm1f;
